const fs = require('fs');
const path = require('path');

// Windows npm bug fix: paths with ampersands ('&') break .cmd shims generated by npm.
// Quotes around 'SET "dp0=%~dp0"' ensure cmd.exe doesn't split on '&'.
if (process.platform === 'win32') {
  const binDir = path.resolve(__dirname, '..', 'node_modules', '.bin');
  if (fs.existsSync(binDir)) {
    const files = fs.readdirSync(binDir).filter((f) => f.endsWith('.cmd'));
    let patchedCount = 0;
    for (const file of files) {
      const filePath = path.join(binDir, file);
      const content = fs.readFileSync(filePath, 'utf8');
      if (content.includes('SET dp0=%~dp0')) {
        fs.writeFileSync(filePath, content.split('SET dp0=%~dp0').join('SET "dp0=%~dp0"'), 'utf8');
        patchedCount++;
      }
    }
    if (patchedCount > 0) {
      console.log(`[postinstall] Patched ${patchedCount} .cmd files for Windows paths containing '&'.`);
    }
  }
}
